"use client";
import { useSyncExternalStore } from "react";

// Responsive media. Every photograph exists in four widths and every large
// video in two tiers plus a poster — generated by scripts/media/* — and the
// data files keep pointing at the base name. These helpers turn a base path
// into the right file for the screen and the connection.
//
// Origin: in the deploy today, on Cloudflare R2 behind media.sklo.studio
// later — the switch is NEXT_PUBLIC_MEDIA_URL and nothing else.

const ORIGIN = (process.env.NEXT_PUBLIC_MEDIA_URL || "").replace(/\/$/, "");
export const IMAGE_WIDTHS = [640, 1280, 1920, 2560];

export function mediaUrl(path = "") {
  if (!path || /^https?:/.test(path)) return path;
  return `${ORIGIN}${path}`;
}

// Folders that never went through the variant script: small UI assets that
// are referenced by their real file name.
const NO_VARIANTS = ["/assets/services/", "/assets/team/", "/assets/home/", "/assets/ogImage", "/assets/Logo", "/assets/heroImage"];
const hasVariants = (src) => src.startsWith("/assets/gallery/");

export function imageVariant(src, width) {
  if (!hasVariants(src)) return mediaUrl(src);
  return mediaUrl(src.replace(/\.(webp|jpe?g|png)$/i, `-${width}.webp`));
}

// `srcSet` for an <img>; the caller sets `sizes` for its layout.
export function imageSrcSet(src) {
  if (!hasVariants(src)) return undefined;
  return IMAGE_WIDTHS.map((w) => `${imageVariant(src, w)} ${w}w`).join(", ");
}

// A sensible default src when srcset is not used (lightbox fallbacks etc).
export function imageSrc(src, width = 1920) {
  return imageVariant(src, width);
}

// ---- video --------------------------------------------------------------

const hasTiers = (src) =>
  /\/assets\/gallery\/(animation|cinemagraph)\//.test(src) || /\/assets\/home\/(faqsection|hero_video)\./.test(src);

export function videoSrc(src, tier = "hd") {
  if (!hasTiers(src)) return mediaUrl(src);
  // The hero's VP9 webm is half the size of its H.264 re-encode, so it stays
  // the HD tier itself; only the SD file is new.
  if (tier === "hd" && src.endsWith(".webm")) return mediaUrl(src);
  return mediaUrl(src.replace(/\.(mp4|webm)$/i, `-${tier}.mp4`));
}

export function videoPoster(src) {
  if (!hasTiers(src)) return undefined;
  return mediaUrl(src.replace(/\.(mp4|webm)$/i, "-poster.webp"));
}

// "sd" on a phone-sized viewport, on a slow or metered connection, or when
// the user asked for reduced data; "hd" otherwise. Read once per render via
// useSyncExternalStore so the server and the first client paint agree
// ("hd"), and the real answer arrives on hydration.
function readTier() {
  if (typeof window === "undefined") return "hd";
  const c = navigator.connection;
  if (c?.saveData) return "sd";
  if (c?.effectiveType && /(^|-)2g|3g/.test(c.effectiveType)) return "sd";
  if (window.innerWidth < 900) return "sd";
  return "hd";
}
const subscribe = (cb) => {
  window.addEventListener("resize", cb);
  navigator.connection?.addEventListener?.("change", cb);
  return () => {
    window.removeEventListener("resize", cb);
    navigator.connection?.removeEventListener?.("change", cb);
  };
};
export function useVideoTier() {
  return useSyncExternalStore(subscribe, readTier, () => "hd");
}
